find:
for (const key of WATCHED.filter((k) => k in pins)) {
  const there = destNamed[name][key];
  if (there === undefined) {
    divergences.push(`catalog-check: ${key} in catalog ${name} is ${pins[key]} here, absent in the destination`);
  } else if (there !== pins[key]) {
    divergences.push(`catalog-check: ${key} in catalog ${name} is ${pins[key]} here, ${there} in the destination`);
  }
}

if (reply === undefined) {
  throw new UnrecordedExchangeError(
    `no recorded exchange for ${exchangeKey(exchange)} - refusing to invent a reply`,
  );
}

if (!Number.isFinite(run.wallMs)) {
  throw new Error(`partial result: run ${mode} n=${n} rep=${rep} has no duration - writing nothing`);
}

failAll(new Error(`transport: peer at ${socketPath} sent a non-JSON line - refusing to continue`));
socket.destroy();
return;

if (!launch.permits.has(normalise(name))) {
  return { refusal: UNAVAILABLE_REFUSAL, refusalClass: "LaunchUnavailable" };
}

if (!table.has(key)) {
  throw new UnrecordedCdpExchangeError(`no recorded exchange for ${key} - refusing to invent a reply`);
}

if (ref === undefined) {
  return { refusal: `no element with id "${params.id}" was ever answered by this daemon - nothing to attest`, refusalClass: "UnknownElement" };
}

if (!existsSync(path)) {
  // Deny by default: the file's absence grants nothing.
  return new Set();
}

try {
  applicationName = await this.nameOf(app);
  if (!isVisible(this.visibility, applicationName)) continue;
} catch (error) {
  // an off-tape read under replay is ignorance, and ignorance surfaces
  // as a refusal - never a skip; a dying app that cannot state its name
  // cannot be granted, so it is skipped like any dying node
  if (error instanceof UnrecordedExchangeError) throw error;
  continue;
}

if (!isVisible(this.visibility, productName(version))) {
  return { elements: [] };
}

try {
  parsed = JSON.parse(text);
} catch {
  throw new MalformedProfilesFileError(
    `the profiles file at ${path} is not valid JSON - a file naming browser identities that cannot be parsed must not silently become "no profiles"`,
  );
}

for (const key of Object.keys(launch.catalog)) {
  if (normalise(key) === normalise(name)) continue;
  if (treeNameOf(key, launch.catalog) !== treeName) continue;
  if (launch.table.ownsName(key) !== undefined) return { refusal: ONE_BROWSER_IDENTITY_REFUSAL, refusalClass: "OneBrowserIdentity", auditApplication: treeName };
}

const teardown = () => {
  void book.closeAll();
};
socket.on("close", teardown);

if (unheard.size > 0) {
  detach();
  pending = null;
  throw new DeafWatchError(
    `the accessibility route registered for its signals, caused one of its own, and never heard ${[...unheard].join(", ")} within ${probeBudgetMs}ms - refusing to hand back a watch that may never speak (element "${subscribedTo}")`,
  );
}

if (disabled(properties)) {
  return {
    actions: [],
    diagnostic: { "mastra-cc/actions-derived-from": "disabled" },
  };
}

const withheld = configurationWithholding(launch, effectClass, application);
if (withheld !== undefined) {
  return { refusal: withheldRefusal(method, effectClass, withheld), refusalClass: "DisabledByConfiguration" };
}

const withheld = configurationWithholding(launch, capability, application);
if (withheld !== undefined) {
  return { capability, availability: "disabled-by-configuration", disabledBy: withheld };
}

if (after.includes("offscreen")) {
  throw observed("bringing this element into view", "offscreen", "on screen");
}

if (!performed) {
  throw new WriteNotObservedError(
    `the application declined to perform ${JSON.stringify(params.action)} - nothing was done`,
  );
}

if (inView !== true) {
  throw new WriteNotObservedError(
    "bringing this element into view reported success, but reading it back found it still outside the viewport - the page performed something other than what was asked",
  );
}

recordAudit({
  application,
  element: answer.application === undefined ? [] : [answer.application],
  scope: "launch",
  cause: causeOf(application),
  outcome: outcomeOf(answer),
});

